var latestRecord = new GlideRecord('x_1440356_riskatla_asset_risk_evaluation'); // Replace 'x' with actual related table name
latestRecord.addQuery('asset_id', current.sys_id); // 'q' is the reference field in Table X pointing to Table T
latestRecord.orderByDesc('sys_created_on'); // Sort by creation time, newest first
latestRecord.setLimit(1); // Only get the latest one
latestRecord.query();

if (latestRecord.next()) {
    gs.addInfoMessage('Latest related record: ' + latestRecord.getDisplayValue());
    // You can now use latestRecord for further logic
}
